// --- Java: Resilience4j (Industry Standard) ---
// Configure the breaker to open if 50% of the last 100 requests fail
CircuitBreakerConfig config = CircuitBreakerConfig.custom()
    .failureRateThreshold(50)
    .slidingWindowSize(100)
    .waitDurationInOpenState(Duration.ofMillis(1000))
    .build();
CircuitBreaker breaker = CircuitBreaker.of("paymentService", config);

// Decorate the risky network call
Supplier<String> decoratedSupplier = CircuitBreaker
    .decorateSupplier(breaker, backendService::doSomething);

// --- Python: Tenacity & PyBreaker ---
# Python uses decorators heavily for this. Tenacity handles intelligent retries with exponential backoff.
@retry(wait=wait_exponential(multiplier=1, min=4, max=10), stop=stop_after_attempt(5))
def make_flaky_request():
    return requests.get("http://flaky-service/api").json()

# PyBreaker is pure circuit breaking
@circuit(failure_threshold=5, recovery_timeout=60)
def call_database():
    return db.query("SELECT * FROM users")
